#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEngine;
[DefaultExecutionOrder(2000)]
public sealed class ArchaeologyHoistContactProbe:MonoBehaviour
{
 public bool ReleaseHeadOverlap{get;private set;}public string ReleaseWithdrawal{get;private set;}public int ReleaseWithdrawalSteps{get;private set;}
 public Component match,artifact,equipment;public string path;public float ReleaseClock{get;private set;}=-1;public int HeadContacts{get;private set;}public int TerrainContacts{get;private set;}public float MaximumHeadForce{get;private set;}float next,contactNext;const BindingFlags Any=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static object Get(object x,string n)=>x.GetType().GetField(n,Any) is FieldInfo f?f.GetValue(x):x.GetType().GetProperty(n,Any).GetValue(x);
 static string PathOf(Transform t)=>t==null?"none":t.parent==null?t.name:PathOf(t.parent)+"/"+t.name;
 public bool Complete=>ReleaseClock>=0&&(float)Get(match,"Clock")-ReleaseClock>=10;
 void Write(string line){if(!string.IsNullOrEmpty(path))File.AppendAllText(path,line+Environment.NewLine);Debug.Log(line);}
 void FixedUpdate()
 {
  if(match==null||artifact==null||equipment==null)return;var body=(Rigidbody)Get(artifact,"body");if(body.isKinematic){float now=(float)Get(match,"Clock");string withdrawing=Get(equipment,"Withdrawal").ToString();if(withdrawing!="None"&&now>=next){next=now+.1f;var heldHead=(Rigidbody)Get(equipment,"head");Write("ARCHAEOLOGY_PHYSICAL_PRE_RELEASE_WITHDRAWAL clock="+now.ToString("R")+" stage="+withdrawing+" steps="+Get(equipment,"WithdrawalSteps")+" initialDepth="+Get(equipment,"InitialWithdrawalDepth")+" initialNormal="+Get(equipment,"InitialWithdrawalNormal")+" head="+heldHead.position.ToString("F6")+" body="+body.position.ToString("F6")+" originalBuriedHold="+body.isKinematic);}return;}float clock=(float)Get(match,"Clock");if(ReleaseClock<0){next=0;ReleaseClock=clock;Write("ARCHAEOLOGY_FIRST_DYNAMIC clock="+clock.ToString("R")+" fixed="+Time.fixedTime.ToString("R"));}if(clock-ReleaseClock>10||clock<next)return;next=clock+.05f;
  var head=(Rigidbody)Get(equipment,"head");var headShape=(Collider)Get(equipment,"headShape");var shape=(BoxCollider)Get(artifact,"shape");var earth=(Component)Get(match,"earth");var crane=Get(equipment,"hoist");bool overlap=Physics.ComputePenetration(headShape,headShape.transform.position,headShape.transform.rotation,shape,shape.transform.position,shape.transform.rotation,out Vector3 direction,out float depth);var joints=body.GetComponents<Joint>().Where(j=>j!=null).ToArray();var sphere=headShape as SphereCollider;float radius=sphere!=null?sphere.radius*Mathf.Max(Mathf.Abs(sphere.transform.lossyScale.x),Mathf.Abs(sphere.transform.lossyScale.y),Mathf.Abs(sphere.transform.lossyScale.z)):0;Vector3 colliderCenter=sphere!=null?sphere.transform.TransformPoint(sphere.center):headShape.bounds.center,colliderBottom=colliderCenter-head.rotation*Vector3.up*radius;
  if(clock==ReleaseClock){ReleaseHeadOverlap=overlap;ReleaseWithdrawal=Get(equipment,"Withdrawal").ToString();ReleaseWithdrawalSteps=(int)Get(equipment,"WithdrawalSteps");}
  Write("ARCHAEOLOGY_WITHDRAWAL stage="+Get(equipment,"Withdrawal")+" steps="+Get(equipment,"WithdrawalSteps")+" completed="+Get(equipment,"CompletedWithdrawals"));
  Write("ARCHAEOLOGY_HOIST_FIXED clock="+clock.ToString("R")+" sinceDynamic="+(clock-ReleaseClock).ToString("R")+" fixed="+Time.fixedTime.ToString("R")+" body="+body.position.ToString("F6")+" v="+body.linearVelocity.ToString("F6")+" av="+body.angularVelocity.ToString("F6")+" q="+body.rotation.ToString("F6")+" bodyLayer="+body.gameObject.layer+" bodyDetect="+body.detectCollisions+" ccd="+body.collisionDetectionMode+" clearance="+Get(artifact,"Clearance")+" stage="+((Array)Get(Get(match,"Rules"),"Stages")).GetValue((int)Get(artifact,"index"))+" crane="+Get(crane,"Stage")+" pickups="+Get(crane,"Pickups")+" releases="+Get(crane,"Releases")+" head="+head.position.ToString("F6")+" headQ="+head.rotation.ToString("F6")+" headShape="+headShape.GetType().Name+" colliderLocalCenter="+(sphere!=null?sphere.center.ToString("F6"):"notSphere")+" colliderRadius="+radius.ToString("R")+" colliderWorldCenter="+colliderCenter.ToString("F6")+" colliderBottomAlongHeadUp="+colliderBottom.ToString("F6")+" pickupOrigin="+head.position.ToString("F6")+" headTrigger="+headShape.isTrigger+" headKinematic="+head.isKinematic+" headOverlap="+overlap+" headDepth="+depth.ToString("R")+" headNormal="+direction.ToString("F6")+" requiredTopAnchor="+body.transform.TransformPoint(Vector3.up*(shape.size.y*.5f)).ToString("F6")+" jointCount="+joints.Length+" joints="+string.Join(";",joints.Select(j=>j.GetType().Name+" connected="+(j.connectedBody!=null?PathOf(j.connectedBody.transform):"WORLD")+" head="+(j.connectedBody==head)+" collision="+j.enableCollision))+" nativeHeadContacts="+HeadContacts+" nativeTerrainContacts="+TerrainContacts+" maxHeadForce="+MaximumHeadForce.ToString("R"));
  var hits=Physics.RaycastAll(new Vector3(body.position.x,24,body.position.z),Vector3.down,100,~0,QueryTriggerInteraction.Ignore).Where(h=>h.collider.attachedRigidbody!=body&&h.collider.attachedRigidbody!=head).OrderBy(h=>h.distance).Take(4).ToArray();if(hits.Length==0)Write("ARCHAEOLOGY_ACTUAL_FLOOR_RAY clock="+clock.ToString("R")+" NONE within y24..-76 at actualbodyXZ");foreach(var hit in hits){bool isTerrain=(bool)earth.GetType().GetMethod("IsTerrain").Invoke(earth,new object[]{hit.collider});Write("ARCHAEOLOGY_ACTUAL_FLOOR_RAY clock="+clock.ToString("R")+" collider="+PathOf(hit.collider.transform)+" type="+hit.collider.GetType().Name+" p="+hit.point.ToString("F6")+" normal="+hit.normal.ToString("F6")+" active="+hit.collider.gameObject.activeInHierarchy+" enabled="+hit.collider.enabled+" digger="+isTerrain+" pairIgnored="+Physics.GetIgnoreCollision(shape,hit.collider)+" layerIgnored="+Physics.GetIgnoreLayerCollision(shape.gameObject.layer,hit.collider.gameObject.layer)+" artifactBottom="+shape.bounds.min.y.ToString("R"));}
 }
 void Contact(Collision c)
 {
  if(match==null||artifact==null||equipment==null)return;var head=(Rigidbody)Get(equipment,"head");bool withHead=c.collider.attachedRigidbody==head;var earth=(Component)Get(match,"earth");bool terrain=(bool)earth.GetType().GetMethod("IsTerrain").Invoke(earth,new object[]{c.collider});if(withHead){HeadContacts++;MaximumHeadForce=Mathf.Max(MaximumHeadForce,c.impulse.magnitude/Time.fixedDeltaTime);}if(terrain)TerrainContacts++;float clock=(float)Get(match,"Clock");if(ReleaseClock<0||clock-ReleaseClock>10||clock<contactNext&&!withHead)return;contactNext=clock+.1f;var p=c.contactCount>0?c.GetContact(0):default;
  Write("ARCHAEOLOGY_REAL_ARTIFACT_COLLISION clock="+clock.ToString("R")+" fixed="+Time.fixedTime.ToString("R")+" other="+PathOf(c.collider.transform)+" head="+withHead+" terrain="+terrain+" impulse="+c.impulse.ToString("F6")+" force="+(c.impulse.magnitude/Time.fixedDeltaTime).ToString("R")+" relativeV="+c.relativeVelocity.ToString("F6")+" point="+p.point.ToString("F6")+" normal="+p.normal.ToString("F6")+" separation="+p.separation.ToString("R"));
 }
 void OnCollisionEnter(Collision c){Contact(c);}void OnCollisionStay(Collision c){Contact(c);}void OnJointBreak(float force){Write("ARCHAEOLOGY_REAL_ARTIFACT_JOINT_BREAK force="+force.ToString("R")+" clock="+Get(match,"Clock"));}
}
#endif
